css:
.print-format {
	padding: 15mm;
}

.receipt-header {
	text-align: center;
	margin-bottom: 20px;
}

.receipt-header h2 {
	margin-bottom: 5px;
}

.receipt-details {
	width: 100%;
	margin-bottom: 20px;
}

.receipt-details td {
	padding: 5px 10px;
}

.receipt-details td:first-child {
	font-weight: bold;
	width: 150px;
}

.receipt-footer {
	text-align: center;
	margin-top: 30px;
	font-size: 12px;
	color: #666;
}
